mapper.select:
SELECT bn.visitTime AS saleTime, bn.patientName AS patientName, bn.gender AS gender, bn.doctor AS doctor, COALESCE( (SELECT ti.name FROM bq_treatment_item ti WHERE ti.projectCode = SUBSTRING_INDEX(SUBSTRING_INDEX(bn.typeString, ' ', 1), ' ', -1) AND ti.deleted = 0 LIMIT 1), (SELECT ei.name FROM bq_examine_item ei WHERE ei.projectCode = SUBSTRING_INDEX(SUBSTRING_INDEX(bn.typeString, ' ', 1), ' ', -1) AND ei.deleted = 0 LIMIT 1), bn.typeString ) AS projectName, bn.typeString AS projectType, bn.amount AS unitPrice, 1 AS quantity, bn.amount AS totalAmount, '已完成' AS chargeStatus FROM bq_bill_not_charged bn WHERE bn.deleted = 0 AND bn.typeString IS NOT NULL AND bn.typeString != '' AND bn.typeString NOT LIKE '%西药%' AND bn.typeString NOT LIKE '%中草药%' AND bn.typeString NOT LIKE '%中成药%'
AND bn.typeString LIKE CONCAT('%', #{projectName}, '%')
AND bn.doctor = #{doctor}
AND bn.visitTime >= #{startTime}
AND bn.visitTime <= #{endTime}
ORDER BY bn.visitTime DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM bq_bill_not_charged bn WHERE bn.deleted = 0 AND bn.typeString IS NOT NULL AND bn.typeString != '' AND bn.typeString NOT LIKE '%西药%' AND bn.typeString NOT LIKE '%中草药%' AND bn.typeString NOT LIKE '%中成药%'
AND bn.typeString LIKE CONCAT('%', #{projectName}, '%')
AND bn.doctor = #{doctor}
AND bn.visitTime >= #{startTime}
AND bn.visitTime <= #{endTime}

SELECT bn.typeString AS projectName, COUNT(*) AS saleTimes, SUM(1) AS totalQuantity, ROUND(COALESCE(SUM(bn.amount), 0), 2) AS totalAmount FROM bq_bill_not_charged bn WHERE bn.deleted = 0 AND bn.typeString IS NOT NULL AND bn.typeString != '' AND bn.typeString NOT LIKE '%西药%' AND bn.typeString NOT LIKE '%中草药%' AND bn.typeString NOT LIKE '%中成药%'
AND bn.typeString LIKE CONCAT('%', #{projectName}, '%')
AND bn.visitTime >= #{startTime}
AND bn.visitTime <= #{endTime}
GROUP BY bn.typeString ORDER BY totalAmount DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM ( SELECT 1 FROM bq_bill_not_charged bn WHERE bn.deleted = 0 AND bn.typeString IS NOT NULL AND bn.typeString != '' AND bn.typeString NOT LIKE '%西药%' AND bn.typeString NOT LIKE '%中草药%' AND bn.typeString NOT LIKE '%中成药%'
AND bn.typeString LIKE CONCAT('%', #{projectName}, '%')
AND bn.visitTime >= #{startTime}
AND bn.visitTime <= #{endTime}
GROUP BY bn.typeString ) t

SELECT COUNT(DISTINCT bn.typeString) AS projectTypeCount, SUM(1) AS totalTimes, ROUND(COALESCE(SUM(bn.amount), 0), 2) AS totalAmount FROM bq_bill_not_charged bn WHERE bn.deleted = 0 AND bn.typeString IS NOT NULL AND bn.typeString != '' AND bn.typeString NOT LIKE '%西药%' AND bn.typeString NOT LIKE '%中草药%' AND bn.typeString NOT LIKE '%中成药%'
AND bn.typeString LIKE CONCAT('%', #{projectName}, '%')
AND bn.visitTime >= #{startTime}
AND bn.visitTime <= #{endTime}
